(()=>{const nav=document.querySelector('.primary-nav'),menu=document.querySelector('#mega-menu');if(!nav||!menu)return;const links=[...nav.querySelectorAll('[data-mega]')],panels=[...menu.querySelectorAll('[data-panel]')];let closeTimer;
function open(name){clearTimeout(closeTimer);panels.forEach(panel=>panel.hidden=panel.dataset.panel!==name);links.forEach(link=>{const active=link.dataset.mega===name;link.classList.toggle('mega-active',active);link.setAttribute('aria-expanded',String(active))});menu.hidden=false}
function close(delay=0){clearTimeout(closeTimer);closeTimer=setTimeout(()=>{menu.hidden=true;links.forEach(link=>{link.classList.remove('mega-active');link.setAttribute('aria-expanded','false')})},delay)}
links.forEach(link=>{link.setAttribute('aria-haspopup','true');link.setAttribute('aria-expanded','false');link.addEventListener('mouseenter',()=>open(link.dataset.mega));link.addEventListener('focus',()=>open(link.dataset.mega))});nav.querySelectorAll('a:not([data-mega])').forEach(link=>{link.addEventListener('mouseenter',()=>close());link.addEventListener('focus',()=>close())});nav.addEventListener('mouseleave',()=>close(180));menu.addEventListener('mouseenter',()=>clearTimeout(closeTimer));menu.addEventListener('mouseleave',()=>close(120));document.addEventListener('keydown',event=>{if(event.key==='Escape'){close();links.find(link=>link.classList.contains('mega-active'))?.focus()}});document.addEventListener('click',event=>{if(!menu.contains(event.target)&&!nav.contains(event.target))close()});})();
